class Solution {
public:
  bool canPermutePalindrome(string s) {
    int count[128] = {};
    for (char c : s) {
      count[(unsigned char)c] ^= 1;
    }
    int odd = 0;
    for (int i = 0; i < 128; i++) {
      odd += count[i];
    }
    return odd <= 1;
  }
};

func canPermutePalindrome(s string) bool {
	count := make([]int, 128)
	for i := 0; i < len(s); i++ {
		count[s[i]] ^= 1
	}
	odd := 0
	for _, c := range count {
		odd += c
	}
	return odd <= 1
}

class Solution {
  public boolean canPermutePalindrome(String s) {
    int[] count = new int[128];
    for (int i = 0; i < s.length(); i++) {
      count[s.charAt(i)] ^= 1;
    }
    int odd = 0;
    for (int c : count) {
      odd += c;
    }
    return odd <= 1;
  }
}

class Solution:
    def canPermutePalindrome(self, s: str) -> bool:
        return sum(v % 2 for v in Counter(s).values()) <= 1

impl Solution {
  pub fn can_permute_palindrome(s: String) -> bool {
    let mut count = [0i32; 128];
    for c in s.bytes() {
      count[c as usize] ^= 1;
    }
    count.iter().sum::<i32>() <= 1
  }
}

const canPermutePalindrome = (s: string): boolean => {
  const count: number[] = new Array(128).fill(0);
  for (const c of s) count[c.charCodeAt(0)] ^= 1;
  return count.reduce((a, b) => a + b, 0) <= 1;
};
